"""Cybersecurity glossary, part 20: more attack methods, malware families, phishing variants and telecom fraud (how criminals work and how to resist).
Row = (id, English name, aliases, category, photo query, local names {fr,sw,rw} or None, en_meaning, en_use, fr_meaning, fr_use, rw_meaning, rw_use, sw_meaning, sw_use)
Awareness-level, protective content: no operational attack instructions. Kinyarwanda and Kiswahili are a DRAFT for review by fluent speakers."""


def R(id_, name, aliases, cat, photo, local, en, fr, rw, sw):
    return (id_, name, aliases, cat, photo, local, en[0], en[1], fr[0], fr[1], rw[0], rw[1], sw[0], sw[1])


TERMS_20 = [
    R("data-diddling", "Data diddling", ["data diddling attack", "falsifying data", "data tampering"], "attacks", "spreadsheet numbers being altered", {"fr": "Falsification de données", "sw": "Kubadilisha data kwa udanganyifu", "rw": "Guhindura amakuru mu buryo bw'uburiganya"},
      ("Deliberately changing data before or while it is entered or processed (for example altering amounts, grades or stock counts) so that the records look normal but are false.", "Often done by insiders. Defences: separation of duties, input checks, audit trails, regular reconciliation and logs that nobody can edit."),
      ("Modifier volontairement des données avant ou pendant leur saisie ou traitement (montants, notes, stocks) pour que les registres semblent normaux mais soient faux.", "Souvent le fait d'initiés. Défenses : séparation des tâches, contrôles de saisie, pistes d'audit, rapprochements réguliers et journaux non modifiables."),
      ("Guhindura amakuru ku bushake mbere cyangwa mu gihe yinjizwa cyangwa atunganywa (amafaranga, amanota, ububiko) kugira ngo inyandiko zisa n'izisanzwe ariko ari ibinyoma.", "Akenshi bikorwa n'abakozi bo imbere. Uburyo bwo kwirinda: gutandukanya inshingano, kugenzura ibyinjijwe, inzira y'igenzura, guhuza ibitabo buri gihe n'ibyanditswe bitahindurwa."),
      ("Kubadilisha data kwa makusudi kabla au wakati wa kuiingiza au kuichakata (kiasi, alama, hesabu ya bidhaa) ili rekodi zionekane za kawaida lakini ni za uongo.", "Mara nyingi hufanywa na watu wa ndani. Ulinzi: mgawanyo wa majukumu, ukaguzi wa ingizo, njia ya ukaguzi, usuluhishi wa mara kwa mara na kumbukumbu zisizobadilishwa.")),
    R("salami-attack", "Salami attack", ["salami slicing", "salami fraud", "penny shaving"], "attacks", "coins being sliced thin", {"fr": "Attaque salami", "sw": "Shambulio la salami", "rw": "Igitero cya salami"},
      ("A fraud that steals many tiny amounts (fractions of a coin or interest) from many accounts so that no single loss is noticed, but the total becomes large.", "Defences: code review of financial software, reconciliation of totals, anomaly detection on rounding and small repeated transfers, and independent audits."),
      ("Une fraude qui vole de très petits montants (fractions de pièce ou d'intérêts) sur de nombreux comptes pour qu'aucune perte ne se remarque, mais que le total devienne élevé.", "Défenses : revue de code des logiciels financiers, rapprochement des totaux, détection d'anomalies sur les arrondis et petits virements répétés, audits indépendants."),
      ("Uburiganya bwiba amafaranga make cyane (agace k'igiceri cyangwa inyungu) kuri konti nyinshi kugira ngo ntihagire igihombo kimwe kimenyekana, ariko hamwe bikaba byinshi.", "Kwirinda: gusuzuma code ya porogaramu z'imari, guhuza ibiteranyo, gutahura ibidasanzwe mu mazamuka no mu kohereza amafaranga make asubiramo, n'igenzura ryigenga."),
      ("Ulaghai wa kuiba kiasi kidogo sana (sehemu ya sarafu au riba) kutoka akaunti nyingi ili hasiwepo hasara moja inayoonekana, lakini jumla ikawa kubwa.", "Ulinzi: ukaguzi wa msimbo wa programu za fedha, usuluhishi wa jumla, kugundua mambo yasiyo ya kawaida kwenye uzungushaji na uhamisho mdogo unaorudiwa, na ukaguzi huru.")),
    R("reverse-shell", "Reverse shell", ["reverse shell attack", "bind shell", "remote shell"], "attacks", "terminal connecting to remote server", {"fr": "Shell inversé", "sw": "Reverse shell", "rw": "Reverse shell"},
      ("A way for an attacker to get a command line on a compromised computer by making that computer connect OUT to the attacker, which often passes through firewalls that only block incoming connections.", "Defenders look for unusual outbound connections, restrict outgoing traffic (egress filtering), monitor processes that launch shells and use EDR to spot them."),
      ("Un moyen pour un attaquant d'obtenir une ligne de commande sur un ordinateur compromis en le faisant se connecter VERS l'attaquant, ce qui traverse souvent les pare-feu qui ne bloquent que les connexions entrantes.", "Les défenseurs cherchent les connexions sortantes inhabituelles, limitent le trafic sortant (filtrage de sortie), surveillent les processus qui lancent des shells et utilisent un EDR."),
      ("Uburyo umushimusi abona umurongo w'amabwiriza kuri mudasobwa yinjiwemo atuma iyo mudasobwa ihamagara umushimusi, bikunze kwambuka firewalls zibuza gusa ibyinjira.", "Abarinzi bashakisha ihuzwa risohoka ridasanzwe, bakabuza amakuru asohoka (egress filtering), bagakurikirana porogaramu zifungura shells kandi bagakoresha EDR."),
      ("Njia ya mshambulizi kupata mstari wa amri kwenye kompyuta iliyovamiwa kwa kuifanya iunganike NJE kwa mshambulizi, ambayo mara nyingi hupita firewalls zinazozuia miunganisho ya kuingia tu.", "Watetezi hutafuta miunganisho ya kutoka isiyo ya kawaida, kuzuia trafiki ya kutoka (egress filtering), kufuatilia michakato inayofungua shells na kutumia EDR.")),
    R("rogue-security-software", "Rogue security software (fake antivirus)", ["rogueware", "fake antivirus", "scareware antivirus", "fake virus alert", "faux antivirus"], "malware", "fake virus warning on screen", {"fr": "Faux antivirus", "sw": "Antivirus bandia", "rw": "Antivirus y'impimbano"},
      ("Software or a pop-up that pretends to be an antivirus, reports invented infections and asks you to pay or install a 'cleaner' that is itself harmful.", "Only install security software from the official store or the vendor's real site; close the page without clicking; never call numbers shown in a pop-up. Run a scan with trusted software."),
      ("Un logiciel ou une fenêtre qui se fait passer pour un antivirus, annonce de fausses infections et demande de payer ou d'installer un « nettoyeur » lui-même malveillant.", "N'installez un antivirus que depuis la boutique officielle ou le vrai site de l'éditeur ; fermez la page sans cliquer ; n'appelez jamais un numéro affiché. Lancez une analyse avec un logiciel fiable."),
      ("Porogaramu cyangwa idirishya ryiyoberanya antivirus, rivuga virusi z'ibinyoma rigusaba kwishyura cyangwa gushyiraho «igikoresho cyo gusukura» ubwacyo cyangiza.", "Shyiraho antivirus ivuye mu iduka ryemewe cyangwa ku rubuga nyarwo rw'uwayikoze; funga urupapuro utakanze; ntuhamagare nimero igaragara. Kora isuzuma ukoresheje porogaramu yizewe."),
      ("Programu au dirisha linalojifanya antivirus, linaripoti maambukizi ya uongo na kukuomba ulipe au usakinishe 'kisafishaji' ambacho chenyewe ni hasidi.", "Sakinisha antivirus kutoka duka rasmi au tovuti halisi ya mtengenezaji tu; funga ukurasa bila kubofya; kamwe usipige namba iliyoonyeshwa. Fanya uchunguzi kwa programu inayoaminika.")),
    R("fleeceware", "Fleeceware", ["fleece ware", "subscription trap app", "overpriced subscription app"], "malware", "phone app with subscription charge", {"fr": "Fleeceware (applications à abonnement abusif)", "sw": "Fleeceware", "rw": "Fleeceware"},
      ("Mobile apps that look free or cheap but charge very high subscriptions, often after a short 'free trial' that is hard to cancel.", "Read the price before the trial ends, set reminders, cancel inside the store's subscription settings, check reviews, and report apps that hide the cost."),
      ("Applications mobiles qui semblent gratuites ou bon marché mais facturent des abonnements très élevés, souvent après un court « essai gratuit » difficile à annuler.", "Lisez le prix avant la fin de l'essai, programmez un rappel, annulez dans les réglages d'abonnement de la boutique, consultez les avis et signalez les applications qui cachent le coût."),
      ("Porogaramu za telefone zisa n'izitishyuza cyangwa zihendutse ariko zishyuza ifatabuguzi rihanitse cyane, akenshi nyuma y'«igerageza ry'ubuntu» rigufi rigoye guhagarika.", "Soma igiciro mbere y'uko igerageza rirangira, shyiraho urwibutso, uhagarike mu igenamiterere ry'ifatabuguzi ry'iduka, usome ibitekerezo kandi umenyeshe porogaramu zihisha igiciro."),
      ("Programu za simu zinazoonekana bure au za bei nafuu lakini zinatoza usajili wa bei kubwa, mara nyingi baada ya 'jaribio la bure' fupi lenye ugumu wa kughairi.", "Soma bei kabla jaribio halijaisha, weka kikumbusho, ghairi kwenye mipangilio ya usajili ya duka, soma maoni na ripoti programu zinazoficha gharama.")),
    R("dns-rebinding", "DNS rebinding", ["dns rebind"], "attacks", "browser connecting to local network device", {"fr": "DNS rebinding", "sw": "DNS rebinding", "rw": "DNS rebinding"},
      ("A web attack that tricks your browser into treating a hostile site as if it were a device on your own network (such as a router or smart device), bypassing the browser's same-origin protection.", "Defences: routers and IoT devices that require a password and check the Host header, DNS filtering that blocks private addresses in public answers, and keeping browsers and firmware updated."),
      ("Une attaque web qui trompe votre navigateur pour qu'il traite un site hostile comme un appareil de votre propre réseau (routeur, objet connecté), contournant la politique de même origine.", "Défenses : routeurs et objets connectés exigeant un mot de passe et vérifiant l'en-tête Host, filtrage DNS bloquant les adresses privées dans les réponses publiques, navigateurs et firmwares à jour."),
      ("Igitero cya web kibeshya urubuga rwawe ngo rufate urubuga rubi nk'igikoresho cyo ku muyoboro wawe (nka router), kikarenga uburinzi bwa same-origin.", "Kwirinda: router n'ibikoresho bya IoT bisaba ijambo ry'ibanga bigenzura Host header, DNS filtering ibuza aderesi z'imbere mu bisubizo bya rubanda, kandi urubuga na firmware bigahora bigezweho."),
      ("Shambulio la wavuti linalodanganya kivinjari chako kutibu tovuti hasidi kama kifaa kwenye mtandao wako (kama router), likipita ulinzi wa same-origin.", "Ulinzi: router na vifaa vya IoT vinavyohitaji nywila na kukagua Host header, uchujaji wa DNS unaozuia anwani za ndani kwenye majibu ya umma, na kuweka kivinjari na firmware kuwa za kisasa.")),
    R("exposed-remote-desktop", "Exposed remote desktop (RDP)", ["rdp exposed", "rdp brute force", "remote desktop protocol attack", "open rdp", "rdp"], "attacks", "remote desktop login screen", {"fr": "Bureau à distance exposé (RDP)", "sw": "RDP iliyo wazi mtandaoni", "rw": "RDP ifunguye kuri interineti"},
      ("Remote Desktop lets someone control a computer from afar. When it is open to the internet with weak passwords, criminals try many passwords and then often install ransomware.", "Never expose RDP directly: put it behind a VPN or gateway, require MFA, use strong unique passwords, limit who may log in, patch, and alert on repeated failed logins."),
      ("Le Bureau à distance permet de contrôler un ordinateur de loin. Ouvert sur internet avec des mots de passe faibles, les criminels essaient de nombreux mots de passe puis installent souvent un rançongiciel.", "N'exposez jamais RDP directement : placez-le derrière un VPN ou une passerelle, exigez la MFA, utilisez des mots de passe forts et uniques, limitez les utilisateurs, appliquez les correctifs et alertez sur les échecs répétés."),
      ("Remote Desktop ituma umuntu agenzura mudasobwa ari kure. Iyo ifunguye kuri interineti ifite amagambo y'ibanga make, abagizi ba nabi bagerageza menshi hanyuma bagashyiraho ransomware.", "Ntuzigere ufungura RDP ku mugaragaro: iyishyire inyuma ya VPN cyangwa gateway, usabe MFA, ukoreshe amagambo y'ibanga akomeye yihariye, ugabanye abemerewe, ushyireho ivugurura kandi umenyeshe iyo kwinjira gutsinzwe kenshi."),
      ("Remote Desktop humruhusu mtu kudhibiti kompyuta akiwa mbali. Ikiwa wazi kwenye intaneti na nywila dhaifu, wahalifu hujaribu nywila nyingi kisha mara nyingi husakinisha ransomware.", "Kamwe usifunue RDP moja kwa moja: iweke nyuma ya VPN au gateway, hitaji MFA, tumia nywila imara za kipekee, punguza wanaoruhusiwa, weka masasisho na toa tahadhari kwa kushindwa kuingia mara kwa mara.")),
    R("default-credentials", "Default credentials", ["default password", "factory password", "default passwords", "admin admin", "mot de passe par defaut"], "attacks", "router label with default password", {"fr": "Identifiants par défaut", "sw": "Nywila za msingi (default)", "rw": "Amagambo y'ibanga asanzwe (default)"},
      ("The username and password a device or program comes with from the factory (like 'admin/admin'). They are public, so attackers try them first on routers, cameras and servers.", "Change every default password at setup, disable unused accounts, give each device a unique strong password, and keep a list in a password manager."),
      ("Le nom d'utilisateur et le mot de passe fournis d'usine avec un appareil ou un logiciel (comme « admin/admin »). Ils sont publics, donc les attaquants les essaient d'abord sur routeurs, caméras et serveurs.", "Changez chaque mot de passe par défaut à l'installation, désactivez les comptes inutilisés, donnez à chaque appareil un mot de passe fort unique et conservez-les dans un gestionnaire de mots de passe."),
      ("Izina n'ijambo ry'ibanga bizana n'igikoresho cyangwa porogaramu ku ruganda (nka «admin/admin»). Biramenyerewe, bityo abashimusi babigerageza mbere kuri router, kamera na seriveri.", "Hindura buri jambo ry'ibanga risanzwe igihe ushyiraho, uhagarike konti zidakoreshwa, uhe buri gikoresho ijambo ry'ibanga rikomeye ryihariye kandi ubibike muri password manager."),
      ("Jina la mtumiaji na nywila zinazokuja na kifaa au programu kiwandani (kama 'admin/admin'). Ni za umma, kwa hiyo washambulizi huzijaribu kwanza kwenye router, kamera na seva.", "Badilisha kila nywila ya msingi wakati wa usanidi, zima akaunti zisizotumika, mpe kila kifaa nywila imara ya kipekee na uzihifadhi kwenye password manager.")),
    R("google-dorking", "Google dorking (search-engine reconnaissance)", ["google dork", "google dorks", "dorking", "search engine hacking"], "attacks", "search engine with advanced operators", {"fr": "Google dorking", "sw": "Google dorking", "rw": "Google dorking"},
      ("Using advanced search operators to find files, login pages or misconfigured systems that are already public on the internet. It reveals mistakes, it does not break in.", "Defenders use it on their own domain to find exposed files; fix by removing sensitive files, using robots rules carefully, authentication, and checking what search engines have indexed."),
      ("Utiliser des opérateurs de recherche avancés pour trouver des fichiers, pages de connexion ou systèmes mal configurés déjà publics. Cela révèle des erreurs, sans pénétrer.", "Les défenseurs l'utilisent sur leur propre domaine pour trouver les fichiers exposés ; corrigez en retirant les fichiers sensibles, en authentifiant, et en vérifiant ce que les moteurs ont indexé."),
      ("Gukoresha amabwiriza y'ishakisha ahambaye kugira ngo ubone dosiye, impapuro zo kwinjira cyangwa sisitemu zashyizweho nabi zisanzwe ari rusange. Bigaragaza amakosa, ntibyinjira ku ngufu.", "Abarinzi barabikoresha ku rubuga rwabo kugira ngo babone dosiye zigaragara; gukosora: gukuraho dosiye z'ibanga, gushyiraho kwemeza, no kugenzura ibyashyizwe mu bubiko bw'ibitabo by'ishakisha."),
      ("Kutumia viendeshaji vya utafutaji vya hali ya juu kupata faili, kurasa za kuingia au mifumo iliyosanidiwa vibaya ambayo tayari ni ya umma. Hufichua makosa, haivunji.", "Watetezi huitumia kwenye kikoa chao kupata faili zilizo wazi; rekebisha kwa kuondoa faili nyeti, kuweka uthibitishaji na kukagua kile injini za utafutaji zimeorodhesha.")),
    R("named-vulnerabilities", "Famous named vulnerabilities (EternalBlue, BlueKeep, Shellshock, PrintNightmare)", ["eternalblue", "bluekeep", "shellshock", "printnightmare", "proxylogon", "follina", "famous vulnerabilities", "named vulnerabilities"], "attacks", "security bug report", {"fr": "Vulnérabilités célèbres (EternalBlue, BlueKeep, Shellshock...)", "sw": "Udhaifu maarufu wenye majina", "rw": "Intege nke zizwi zifite amazina"},
      ("Some serious flaws got names. EternalBlue (Windows file sharing, used by WannaCry), BlueKeep (Remote Desktop), Shellshock (Bash), PrintNightmare (Windows printing) and ProxyLogon (Exchange mail servers) let attackers run code on unpatched systems.", "Lesson: unpatched systems are attacked within days. Apply security updates quickly, remove services you do not need from the internet, and watch the CISA/vendor advisories."),
      ("Certaines failles graves ont reçu un nom. EternalBlue (partage de fichiers Windows, utilisée par WannaCry), BlueKeep (Bureau à distance), Shellshock (Bash), PrintNightmare (impression Windows) et ProxyLogon (serveurs Exchange) permettent d'exécuter du code sur des systèmes non corrigés.", "Leçon : les systèmes non corrigés sont attaqués en quelques jours. Appliquez vite les mises à jour, retirez d'internet les services inutiles et suivez les avis des éditeurs et de la CISA."),
      ("Intege nke zimwe zikomeye zahawe amazina. EternalBlue (gusangira dosiye kwa Windows, yakoreshejwe na WannaCry), BlueKeep (Remote Desktop), Shellshock (Bash), PrintNightmare (gucapa kwa Windows) na ProxyLogon (seriveri za Exchange) zituma abashimusi bakoresha code kuri sisitemu zitavuguruwe.", "Isomo: sisitemu zitavuguruwe ziterwa mu minsi mike. Shyiraho ivugurura vuba, ukure kuri interineti serivisi udakeneye kandi ukurikire amatangazo y'abakora porogaramu na CISA."),
      ("Hitilafu zingine kubwa zilipewa majina. EternalBlue (kushiriki faili Windows, ilitumiwa na WannaCry), BlueKeep (Remote Desktop), Shellshock (Bash), PrintNightmare (uchapishaji Windows) na ProxyLogon (seva za Exchange) huruhusu kuendesha msimbo kwenye mifumo isiyosasishwa.", "Funzo: mifumo isiyosasishwa hushambuliwa ndani ya siku. Weka masasisho haraka, ondoa huduma zisizohitajika kwenye intaneti na fuata matangazo ya watengenezaji na CISA.")),
    R("crypto-protocol-attacks", "Attacks on old encryption protocols (POODLE, BEAST, Logjam, FREAK, DROWN)", ["poodle", "beast attack", "logjam", "freak attack", "drown attack", "sweet32", "padding oracle", "downgrade attack", "ssl attacks"], "crypto", "padlock with crack", {"fr": "Attaques sur d'anciens protocoles de chiffrement", "sw": "Mashambulizi dhidi ya itifaki za zamani za usimbaji", "rw": "Ibitero ku miyoboro ya kera ya encryption"},
      ("Many named attacks exploit old versions of SSL/TLS or weak ciphers: POODLE and BEAST (old SSL/TLS), Logjam and FREAK (weak export-grade keys), DROWN (SSLv2), padding-oracle and downgrade attacks (forcing a weaker version).", "Defence: disable SSL and TLS 1.0/1.1, use TLS 1.2 or 1.3 with modern cipher suites, keep servers updated and test your site with a TLS scanner."),
      ("De nombreuses attaques nommées exploitent d'anciennes versions de SSL/TLS ou des chiffrements faibles : POODLE et BEAST (anciens SSL/TLS), Logjam et FREAK (clés faibles d'export), DROWN (SSLv2), attaques par oracle de bourrage et de rétrogradation (forcer une version plus faible).", "Défense : désactiver SSL et TLS 1.0/1.1, utiliser TLS 1.2 ou 1.3 avec des suites modernes, garder les serveurs à jour et tester son site avec un scanner TLS."),
      ("Ibitero byinshi bifite amazina bikoresha verisiyo za kera za SSL/TLS cyangwa ciphers zoroheje: POODLE na BEAST (SSL/TLS za kera), Logjam na FREAK (urufunguzo rworoshye rwa export), DROWN (SSLv2), padding-oracle na downgrade (guhatira verisiyo yoroheje).", "Kwirinda: guhagarika SSL na TLS 1.0/1.1, gukoresha TLS 1.2 cyangwa 1.3 na cipher suites zigezweho, kuvugurura seriveri no kugerageza urubuga rwawe na TLS scanner."),
      ("Mashambulizi mengi yenye majina hutumia matoleo ya zamani ya SSL/TLS au ciphers dhaifu: POODLE na BEAST (SSL/TLS za zamani), Logjam na FREAK (funguo dhaifu za export), DROWN (SSLv2), padding-oracle na downgrade (kulazimisha toleo dhaifu).", "Ulinzi: zima SSL na TLS 1.0/1.1, tumia TLS 1.2 au 1.3 na cipher suites za kisasa, sasisha seva na ujaribu tovuti yako kwa TLS scanner.")),
    R("cryptanalysis", "Cryptanalysis (known-plaintext, chosen-plaintext, frequency analysis)", ["known plaintext", "chosen plaintext", "frequency analysis", "breaking ciphers", "codebreaking", "cryptanalyse"], "crypto", "cipher wheel and codebreaking", {"fr": "Cryptanalyse", "sw": "Uchambuzi wa kriptografia (cryptanalysis)", "rw": "Cryptanalysis (gusesengura no gucamo encryption)"},
      ("The science of breaking or weakening ciphers without the key. Classic methods include frequency analysis of letters (which breaks the Caesar and Vigenère ciphers) and known- or chosen-plaintext attacks that use samples of readable text.", "Why it matters: it is how weak ciphers are found. Never invent your own cipher; use standard, public, well-tested algorithms such as AES and keep keys secret."),
      ("La science qui consiste à casser ou affaiblir des chiffrements sans la clé. Méthodes classiques : analyse de fréquence des lettres (qui casse César et Vigenère) et attaques à texte clair connu ou choisi utilisant des échantillons lisibles.", "Pourquoi c'est important : c'est ainsi qu'on trouve les chiffrements faibles. N'inventez jamais votre propre chiffrement ; utilisez des algorithmes standard, publics et éprouvés comme AES et gardez les clés secrètes."),
      ("Siyansi yo gucamo cyangwa kugabanya imbaraga za ciphers nta rufunguzo. Uburyo bwa kera: isesengura ry'inshuro z'inyuguti (rica Caesar na Vigenère) n'ibitero bikoresha inyandiko izwi cyangwa yatoranyijwe.", "Impamvu bifite akamaro: ni ko ciphers zoroheje zibonwa. Ntuzigere wihimbira cipher yawe; koresha algorithms zisanzwe, rusange kandi zageragejwe nka AES kandi ubike imfunguzo mu ibanga."),
      ("Sayansi ya kuvunja au kudhoofisha ciphers bila ufunguo. Mbinu za zamani: uchambuzi wa masafa ya herufi (huvunja Caesar na Vigenère) na mashambulizi ya maandishi yanayojulikana au yaliyochaguliwa.", "Kwa nini ni muhimu: ndivyo ciphers dhaifu hugunduliwa. Kamwe usibuni cipher yako mwenyewe; tumia algorithms za kawaida, za umma na zilizojaribiwa kama AES na uweke funguo siri.")),
    R("html-smuggling", "HTML smuggling and risky attachment types", ["html smuggling", "iso attachment", "lnk malware", "onenote malware", "double extension", "malicious attachment types", "dangerous file types"], "malware", "email attachment warning", {"fr": "HTML smuggling et pièces jointes à risque", "sw": "HTML smuggling na viambatisho hatari", "rw": "HTML smuggling n'ubwoko bwa dosiye buteje akaga"},
      ("Criminals hide malware in file types that people trust or that bypass filters: HTML pages that assemble a file on your computer, disk images (ISO), shortcut files (.lnk), documents with macros, OneNote files, archives with passwords, and names like 'invoice.pdf.exe' (double extension).", "Turn on 'show file extensions', block macros and executable attachments, do not open unexpected files even from known senders, and use mail filtering and a sandbox."),
      ("Les criminels cachent des logiciels malveillants dans des types de fichiers de confiance ou qui contournent les filtres : pages HTML qui assemblent un fichier sur votre ordinateur, images disque (ISO), raccourcis (.lnk), documents avec macros, fichiers OneNote, archives protégées, noms comme « facture.pdf.exe » (double extension).", "Activez l'affichage des extensions, bloquez macros et pièces jointes exécutables, n'ouvrez pas de fichiers inattendus même de contacts connus, et utilisez filtrage des e-mails et bac à sable."),
      ("Abagizi ba nabi bahisha malware mu bwoko bwa dosiye abantu bizera cyangwa zirengera filters: impapuro za HTML zubaka dosiye kuri mudasobwa yawe, ISO, shortcuts (.lnk), inyandiko zirimo macros, dosiye za OneNote, archives zifite ijambo ry'ibanga, n'amazina nka «fagitire.pdf.exe» (extension ebyiri).", "Fungura kwerekana extensions za dosiye, ubuze macros na dosiye zikora, ntufungure dosiye zitateganyijwe nubwo zaturutse ku bantu uzi, kandi ukoreshe filters z'imeri na sandbox."),
      ("Wahalifu huficha programu hasidi katika aina za faili zinazoaminika au zinazopita vichujio: kurasa za HTML zinazojenga faili kwenye kompyuta yako, picha za diski (ISO), njia za mkato (.lnk), hati zenye macros, faili za OneNote, kumbukumbu zenye nywila, na majina kama 'ankara.pdf.exe' (kiendelezi mara mbili).", "Washa 'onyesha viendelezi vya faili', zuia macros na viambatisho vinavyotekelezeka, usifungue faili zisizotarajiwa hata kutoka kwa watu unaowajua, na tumia uchujaji wa barua pepe na sandbox.")),
    R("display-name-spoofing", "Display-name spoofing and reply-to tricks", ["display name spoof", "display name spoofing", "reply-to mismatch", "reply to trick", "sender name spoofing", "faux nom d'expediteur"], "social", "email header with sender name", {"fr": "Usurpation du nom d'affichage", "sw": "Kughushi jina la mtumaji", "rw": "Kwiyitirira izina ry'uwohereje"},
      ("In many mail apps only the sender's NAME is shown, so a criminal writes 'Your Bank' or the boss's name while the real address is different. Another trick: a Reply-To address that sends your answer to the criminal.", "Always look at the full address (tap the name), be suspicious when the name and address do not match, and confirm money or password requests by another channel."),
      ("Dans beaucoup d'applications de messagerie seul le NOM de l'expéditeur s'affiche : un criminel écrit « Votre Banque » ou le nom du patron alors que l'adresse réelle est différente. Autre astuce : une adresse de réponse (Reply-To) qui envoie votre réponse au criminel.", "Regardez toujours l'adresse complète (touchez le nom), méfiez-vous quand nom et adresse ne correspondent pas, et confirmez par un autre canal toute demande d'argent ou de mot de passe."),
      ("Muri porogaramu nyinshi z'imeri hagaragara gusa IZINA ry'uwohereje, bityo umugizi wa nabi yandika «Banki yawe» cyangwa izina ry'umuyobozi mu gihe aderesi nyayo ari indi. Ubundi buryo: aderesi ya Reply-To yohereza igisubizo cyawe ku mugizi wa nabi.", "Reba buri gihe aderesi yuzuye (kanda ku izina), ugire amakenga iyo izina na aderesi bidahuye, kandi wemeze ibisabwa by'amafaranga cyangwa ijambo ry'ibanga unyuze ku wundi muyoboro."),
      ("Katika programu nyingi za barua pepe JINA la mtumaji tu huonyeshwa, hivyo mhalifu anaandika 'Benki Yako' au jina la bosi ilhali anwani halisi ni tofauti. Hila nyingine: anwani ya Reply-To inayotuma jibu lako kwa mhalifu.", "Daima angalia anwani kamili (gusa jina), kuwa na shaka jina na anwani visipolingana, na thibitisha maombi ya pesa au nywila kwa njia nyingine.")),
    R("oauth-consent-phishing", "OAuth consent and device-code phishing", ["oauth consent phishing", "device code phishing", "illicit consent grant", "malicious app permission", "consent phishing"], "social", "app permission request screen", {"fr": "Hameçonnage par consentement OAuth", "sw": "Hadaa ya ridhaa ya OAuth", "rw": "Phishing ya OAuth consent"},
      ("Instead of stealing your password, the attacker gets you to click 'Allow' for a harmful app (OAuth consent) or to type a short code on a real login page (device-code phishing), giving them access to your mail or files with no password needed and often surviving a password change.", "Read what an app asks for before allowing it, only allow known apps, review and remove connected apps regularly, and never enter a code you did not request on a device you control."),
      ("Au lieu de voler votre mot de passe, l'attaquant vous fait cliquer sur « Autoriser » pour une application nuisible (consentement OAuth) ou saisir un court code sur une vraie page de connexion (hameçonnage par code d'appareil), obtenant l'accès à vos e-mails ou fichiers sans mot de passe, souvent même après changement du mot de passe.", "Lisez ce que demande une application avant d'autoriser, n'autorisez que des applications connues, passez en revue et supprimez régulièrement les applications connectées, et ne saisissez jamais un code que vous n'avez pas demandé."),
      ("Aho kwiba ijambo ry'ibanga, umushimusi agutuma ukanda «Emerera» kuri porogaramu mbi (OAuth consent) cyangwa ukandika kode ngufi ku rupapuro nyarwo rwo kwinjira (device-code phishing), akabona imeri cyangwa dosiye zawe nta jambo ry'ibanga, kenshi bikaramba no nyuma yo guhindura ijambo ry'ibanga.", "Soma ibyo porogaramu isaba mbere yo kwemera, emerera izizwi gusa, genzura kandi ukureho porogaramu zihujwe buri gihe, kandi ntukandike kode utasabye."),
      ("Badala ya kuiba nywila yako, mshambulizi anakufanya ubofye 'Ruhusu' kwa programu hasidi (OAuth consent) au uandike msimbo mfupi kwenye ukurasa halisi wa kuingia (device-code phishing), akipata barua pepe au faili zako bila nywila, mara nyingi hata baada ya kubadilisha nywila.", "Soma programu inachoomba kabla ya kuruhusu, ruhusu programu zinazojulikana tu, kagua na ondoa programu zilizounganishwa mara kwa mara, na kamwe usiingize msimbo ambao hukuomba.")),
    R("collaboration-phishing", "Phishing on Teams, Slack, LinkedIn and social platforms", ["teams phishing", "slack phishing", "linkedin phishing", "calendar invite phishing", "collaboration app phishing", "social platform phishing"], "social", "chat app with suspicious link", {"fr": "Hameçonnage sur Teams, Slack, LinkedIn", "sw": "Hadaa kwenye Teams, Slack, LinkedIn", "rw": "Phishing kuri Teams, Slack, LinkedIn"},
      ("Phishing is not only by email: criminals send fake chat messages, shared documents, calendar invites, job offers and 'connection requests' on work and social platforms, often from a hijacked real account so they look trusted.", "Treat links and files in chats like email: verify unexpected requests by another channel, check the sender's profile, be careful with job and investment offers, and report suspicious accounts."),
      ("L'hameçonnage ne passe pas que par e-mail : les criminels envoient de faux messages de discussion, documents partagés, invitations de calendrier, offres d'emploi et « demandes de connexion » sur les plateformes de travail et sociales, souvent depuis un vrai compte piraté pour paraître fiables.", "Traitez liens et fichiers des discussions comme des e-mails : vérifiez les demandes inattendues par un autre canal, contrôlez le profil de l'expéditeur, méfiez-vous des offres d'emploi et d'investissement, et signalez les comptes suspects."),
      ("Phishing ntiba gusa mu imeri: abagizi ba nabi bohereza ubutumwa bw'impimbano mu mashakiro, dosiye zisangiwe, ubutumire bw'ikalendari, amatangazo y'akazi n'«ubusabe bwo kuba incuti» ku mbuga z'akazi n'iz'imbuga nkoranyambaga, kenshi bakoresha konti nyakuri yafashwe kugira ngo bizerwe.", "Fata link na dosiye mu mashakiro nk'imeri: genzura ubusabe butateganyijwe unyuze ku wundi muyoboro, reba umwirondoro w'uwohereje, witondere amatangazo y'akazi n'ay'ishoramari kandi umenyeshe konti zikekwa."),
      ("Hadaa haipo si kwa barua pepe tu: wahalifu hutuma ujumbe bandia wa mazungumzo, hati zilizoshirikiwa, mialiko ya kalenda, ofa za kazi na 'maombi ya muunganisho' kwenye majukwaa ya kazi na ya kijamii, mara nyingi kutoka akaunti halisi iliyodukuliwa ili waaminike.", "Chukulia viungo na faili kwenye mazungumzo kama barua pepe: thibitisha maombi yasiyotarajiwa kwa njia nyingine, kagua wasifu wa mtumaji, kuwa makini na ofa za kazi na uwekezaji na ripoti akaunti za kutiliwa shaka.")),
    R("call-forwarding-fraud", "Call-forwarding and SMS-interception fraud", ["call forwarding fraud", "sms interception", "2fa bypass", "otp bot", "otp interception", "forwarded calls scam"], "attacks", "phone with call forwarding setting", {"fr": "Fraude au renvoi d'appel et interception de SMS", "sw": "Ulaghai wa kuelekeza simu na kunasa SMS", "rw": "Uburiganya bwo kohereza ahandi ihamagara no gufata SMS"},
      ("Criminals trick you into dialling a code that forwards your calls or texts to them, or use 'OTP bots' that phone you pretending to be your bank to make you read out the one-time code, so they can pass two-step verification.", "Never dial codes a caller gives you, never read an OTP to anyone, check your phone's forwarding settings, and tell your operator at once if your calls or SMS stop arriving."),
      ("Les criminels vous font composer un code qui renvoie vos appels ou SMS vers eux, ou utilisent des « bots OTP » qui vous appellent en se faisant passer pour votre banque pour vous faire lire le code à usage unique et passer la double vérification.", "Ne composez jamais un code donné par un appelant, ne lisez jamais un OTP à quiconque, vérifiez les réglages de renvoi d'appel et prévenez votre opérateur si vos appels ou SMS n'arrivent plus."),
      ("Abagizi ba nabi bagutuma ukanda kode yohereza ahandi ihamagara cyangwa SMS zawe, cyangwa bagakoresha «OTP bots» zigutera telefone ziyitirira banki kugira ngo usome kode y'inshuro imwe maze bambuke kwemeza mu byiciro bibiri.", "Ntukande kode uhawe n'uguhamagaye, ntusome OTP ku muntu uwo ari we wese, genzura igenamiterere ryo kohereza ihamagara ahandi kandi umenyeshe sosiyete ya telefone ako kanya niba ihamagara cyangwa SMS bitakigera."),
      ("Wahalifu hukudanganya upige msimbo unaoelekeza simu au SMS zako kwao, au hutumia 'OTP bots' zinazokupigia zikijifanya benki ili usome msimbo wa mara moja na wapite uthibitishaji wa hatua mbili.", "Kamwe usipige msimbo uliopewa na mpigaji, usisome OTP kwa mtu yeyote, kagua mipangilio ya kuelekeza simu na mjulishe mtoa huduma wako mara moja simu au SMS zikiacha kufika.")),
    R("irsf-premium-rate", "International revenue share fraud and premium-rate scams", ["irsf", "premium rate fraud", "premium rate number scam", "artificial inflation traffic", "toll fraud", "wangiri one ring"], "attacks", "phone bill with high charges", {"fr": "Fraude au partage de revenus international et numéros surtaxés", "sw": "Ulaghai wa mapato ya kimataifa na namba za gharama kubwa", "rw": "Uburiganya bw'inyungu mpuzamahanga n'inimero zihenze"},
      ("Fraudsters generate calls or SMS to premium or foreign numbers they control and share the revenue; individuals are hit by 'one-ring' missed calls that tempt you to call back an expensive number, or by messages that subscribe you to costly services.", "Do not call back unknown foreign or premium numbers, block them, check your bill and airtime for unknown charges, and ask your operator to bar premium services."),
      ("Les fraudeurs génèrent des appels ou SMS vers des numéros surtaxés ou étrangers qu'ils contrôlent et se partagent les revenus ; les particuliers sont visés par des appels manqués « une sonnerie » qui incitent à rappeler un numéro coûteux, ou par des messages qui abonnent à des services chers.", "Ne rappelez pas les numéros étrangers ou surtaxés inconnus, bloquez-les, vérifiez factures et crédit pour des frais inconnus et demandez à l'opérateur de bloquer les services surtaxés."),
      ("Abagizi ba nabi bakora ihamagara cyangwa SMS ku nimero zihenze cyangwa zo mu mahanga bagenzura bagasangira inyungu; abantu ku giti cyabo bagirwaho ingaruka n'ihamagara «rimwe rya telefone» ritera kugarura ihamagara kuri nimero ihenze, cyangwa n'ubutumwa bukwandikisha kuri serivisi zihenze.", "Ntugarure ihamagara kuri nimero zitazwi zo mu mahanga cyangwa zihenze, uzihagarike, ugenzure fagitire na airtime ku mafaranga atazwi kandi usabe sosiyete ya telefone guhagarika serivisi zihenze."),
      ("Matapeli huzalisha simu au SMS kwa namba za gharama kubwa au za nje wanazozidhibiti na kugawana mapato; watu binafsi hulengwa na simu zilizokosekana za 'mlio mmoja' zinazokushawishi upige tena namba ghali, au ujumbe unaokusajili kwa huduma ghali.", "Usipige tena namba za nje au ghali zisizojulikana, zizuie, kagua bili na airtime kwa gharama zisizojulikana na mwombe mtoa huduma azuie huduma za gharama kubwa.")),
    R("caller-id-authentication", "Caller-ID authentication (STIR/SHAKEN) and robocalls", ["stir shaken", "caller id authentication", "robocall", "robocalls", "spam calls", "call spoofing defence"], "network", "phone call with verified badge", {"fr": "Authentification de l'appelant (STIR/SHAKEN) et appels automatisés", "sw": "Uthibitishaji wa mpigaji (STIR/SHAKEN) na robocalls", "rw": "Kwemeza uhamagaye (STIR/SHAKEN) n'ihamagara rya robo"},
      ("Caller ID can be faked. STIR/SHAKEN is a set of standards that lets phone networks digitally sign calls so the receiving network can tell whether the displayed number is genuine. Robocalls are automatic calls, often scams.", "It reduces but does not end spoofing, and is not available everywhere. Still treat any unexpected caller with caution, hang up and call back on an official number."),
      ("Le numéro affiché peut être falsifié. STIR/SHAKEN est un ensemble de normes permettant aux réseaux de signer numériquement les appels afin que le réseau récepteur sache si le numéro affiché est authentique. Les appels automatisés (robocalls) sont souvent des arnaques.", "Cela réduit sans supprimer l'usurpation et n'existe pas partout. Méfiez-vous de tout appelant inattendu, raccrochez et rappelez sur un numéro officiel."),
      ("Nimero igaragara ishobora guhimbwa. STIR/SHAKEN ni ibipimo bituma imiyoboro ya telefone isinya ihamagara kugira ngo umuyoboro wakira umenye niba nimero igaragara ari impamo. Robocalls ni ihamagara ryikora, kenshi ry'uburiganya.", "Bigabanya ariko ntibikuraho guhimba kandi ntibiboneka hose. Ukomeze kugira amakenga ku uguhamagaye utateganyijwe, ukate hanyuma uhamagare nimero yemewe."),
      ("Namba ya mpigaji inaweza kughushiwa. STIR/SHAKEN ni viwango vinavyoruhusu mitandao ya simu kusaini simu kidijitali ili mtandao unaopokea ujue kama namba inayoonyeshwa ni halisi. Robocalls ni simu za kiotomatiki, mara nyingi utapeli.", "Hupunguza lakini haikomeshi kughushi na haipatikani kila mahali. Bado chukulia mpigaji yeyote asiyetarajiwa kwa tahadhari, kata simu na upige tena kwa namba rasmi.")),
]
